  const PaneModes({
    required this.pane,
    required this.mouse,
    required this.altScreen,
    this.kitty = 0,
  });

  /// The `t` discriminator this class always carries. It is a property of
  /// the type, not a field: a caller who could set it could set it wrong.
  static const String type = 'pane_modes';

