  factory PaneModes.fromJson(Map<String, Object?> j) => PaneModes(
        pane: asInt(j['pane']),
        mouse: asBool(j['mouse']),
        altScreen: asBool(j['alt_screen']),
        kitty: asInt(j['kitty']),
      );

  Map<String, Object?> toJson() => {
        't': type,
        'pane': pane,
        'mouse': mouse,
        'alt_screen': altScreen,
        if (kitty != 0) 'kitty': kitty,
      };
}

